// src/utils/planGate.ts
// Utilitário para verificar acesso a features baseado no plano do usuário

import { getUserPlan as getUserPlanFromConfig, type UserPlan } from '../config/features';

/**
 * Verifica se o usuário pode usar voz
 */
export async function canUseVoice(): Promise<boolean> {
  const plan = await getUserPlanFromConfig();
  return plan !== 'free';
}

/**
 * Verifica se o usuário pode usar IA completa
 */
export async function canUseFullAI(): Promise<boolean> {
  const plan = await getUserPlanFromConfig();
  return plan !== 'free';
}

/**
 * Versão síncrona (retorna false se não conseguir verificar)
 * Útil para renderização inicial
 */
export function canUseVoiceSync(plan?: UserPlan): boolean {
  const userPlan = plan || 'free';
  return userPlan !== 'free';
}

/**
 * Versão síncrona para IA completa
 */
export function canUseFullAISync(plan?: UserPlan): boolean {
  const userPlan = plan || 'free';
  return userPlan !== 'free';
}




























